# 题目描述

有n个任务，每个任务都有一个开始时间和一个结束时间，现在要安排这些任务的执行顺序，使得所有任务都能被顺利地执行完。如果存在多种可行方案，则输出最早完成所有任务的时间。

# 输入格式

第一行为n，表示有n个任务。接下来n行，每行两个数，分别为开始时间和结束时间。

# 输出格式

一行，包含一个整数，表示最早完成所有任务的时间。

# 样例输入

4
10 20
30 50
60 70
80 90

# 样例输出

100

# 评测用例规模与约定

对于所有评测用例，1 ≤ n ≤ 1000。
#include <iostream>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    int a[n][m];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            cin >> a[i][j];

    int b[m][n];
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            b[j][i] = a[i][j];
        }
    }

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << b[i][j] << " ";
        }
        cout << endl;
    }
}
#include <iostream>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    int a[n];
    for (int i = 0; i < n; ++i)
        cin >> a[i];

    int b[m];
    for (int i = 0; i < m; ++i) {
        cin >> b[i];
    }

    bool flag = false;
    for (int i = 0; i < n; ++i) {
        if (a[i] == b[0]) {
            int j = 1;
            while (j < m && a[i + j] == b[j])
                ++j;

            if (j == m) {
                flag = true;
                break;
            }
        }
    }

    cout << (flag ? "Yes" : "No") << endl;
}
